def find_rotation_count(A):
    """Write a function to find the number of rotations in a circularly sorted array."""
    n = len(A)
    if n == 0:
        return 0
    low, high = 0, n - 1
    while low < high:
        mid = (low + high) // 2
        if A[mid] > A[high]:
            low = mid + 1
        elif A[mid] < A[high]:
            high = mid
        else:
            high -= 1
    return low
